const exactData = await browserjs(tabId, () => {
  const card1 = document.querySelector('[data-qa-target="pro-card-natural-1"]');
  const card2 = document.querySelector('[data-qa-target="pro-card-natural-2"]');

  function findDataInFiber(el) {
    const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber$'));
    let fiber = el[fiberKey];
    while (fiber) {
      if (fiber.memoizedProps) {
        for (const [k, v] of Object.entries(fiber.memoizedProps)) {
          if (v && typeof v === 'object') {
            const str = JSON.stringify(v);
            if (str.includes('distance') || str.includes('address') || str.includes('Eggert') || str.includes('Hanrahan')) {
              return v;
            }
          }
        }
      }
      fiber = fiber.return;
    }
    return null;
  }

  return {
    d1: findDataInFiber(card1),
    d2: findDataInFiber(card2)
  };
});

