const tabId = 248688717;

const exactData = await browserjs(tabId, () => {
  const card1 = document.querySelector('[data-qa-target="pro-card-natural-1"]');
  const card2 = document.querySelector('[data-qa-target="pro-card-natural-2"]');

  function getCardData(el) {
    if (!el) return null;
    const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber$'));
    let fiber = el[fiberKey];
    while (fiber) {
      const props = fiber.memoizedProps;
      if (props) {
        // Look for properties on props
        for (const k of Object.keys(props)) {
          if (k === 'provider' || k === 'card' || k === 'item' || k === 'data' || k === 'result') {
            return props[k];
          }
          if (props[k] && typeof props[k] === 'object') {
            if (props[k].displayName || props[k].providerId || props[k].distance || props[k].address) {
              return {
                name: props[k].displayName || props[k].fullName || props[k].name,
                distance: props[k].distance,
                rating: props[k].rating,
                address: props[k].address,
                location: props[k].location,
                locations: props[k].locations,
                practice: props[k].practice
              };
            }
          }
        }
      }
      fiber = fiber.return;
    }
    return null;
  }

  return {
    d1: getCardData(card1),
    d2: getCardData(card2)
  };
});

