const tabId = 248688717;

const apiData = await browserjs(tabId, () => {
  const chunks = window.__next_f || [];
  let fullStr = "";
  for (const chunk of chunks) {
    if (Array.isArray(chunk) && typeof chunk[1] === 'string') {
      fullStr += chunk[1];
    }
  }

  // Find occurrences of Eggert and Hanrahan or provider search results
  // Let's search for providers array
  const providerMatches = [];
  const regex = /"displayName":\s*"([^"]+)"[^}]+?"distance":\s*([0-9.]+)/g;
  let match;
  while ((match = regex.exec(fullStr)) !== null) {
    providerMatches.push({ name: match[1], distance: match[2] });
  }

  // Also let's extract snippets around Eggert and Hanrahan
  const eggertIdx = fullStr.indexOf("Eggert");
  const eggertSnippet = eggertIdx !== -1 ? fullStr.slice(Math.max(0, eggertIdx - 500), eggertIdx + 1500) : null;

  const hanrahanIdx = fullStr.indexOf("Hanrahan");
  const hanrahanSnippet = hanrahanIdx !== -1 ? fullStr.slice(Math.max(0, hanrahanIdx - 500), hanrahanIdx + 1500) : null;

  return {
    chunkCount: chunks.length,
    fullLength: fullStr.length,
    providerMatches,
    eggertSnippet,
    hanrahanSnippet
  };
});

console.log("Full length:", apiData.fullLength);
console.log("Provider matches count:", apiData.providerMatches.length);
console.log("Eggert snippet:\n", apiData.eggertSnippet);
console.log("Hanrahan snippet:\n", apiData.hanrahanSnippet);

