const tabId = 248688717;

const cardProps = await browserjs(tabId, () => {
  function getReactProps(el) {
    if (!el) return null;
    const key = Object.keys(el).find(k => k.startsWith('__reactProps$') || k.startsWith('__reactFiber$'));
    return key ? el[key] : null;
  }

  const card1 = document.querySelector('[data-qa-target="pro-card-natural-1"]');
  const card2 = document.querySelector('[data-qa-target="pro-card-natural-2"]');

  function extractInterestingProps(node, depth = 0) {
    if (!node || depth > 10) return null;
    if (node.provider || node.cardData || node.searchResult || node.data) {
      return node.provider || node.cardData || node.searchResult || node.data;
    }
    // Search children or memoizedProps
    if (node.memoizedProps) {
      const res = extractInterestingProps(node.memoizedProps, depth + 1);
      if (res) return res;
    }
    if (node.props) {
      const res = extractInterestingProps(node.props, depth + 1);
      if (res) return res;
    }
    if (node.child) {
      const res = extractInterestingProps(node.child, depth + 1);
      if (res) return res;
    }
    return null;
  }

  const p1 = getReactProps(card1);
  const p2 = getReactProps(card2);

  // Let's also check if there are any distance attributes, or data in card elements
  return {
    p1Keys: p1 ? Object.keys(p1) : null,
    p2Keys: p2 ? Object.keys(p2) : null,
    card1Text: card1?.innerText,
    card2Text: card2?.innerText
  };
});

console.log(JSON.stringify(cardProps, null, 2));

