const tabId = 248688717;

const exactObj = await browserjs(tabId, () => {
  const card1 = document.querySelector('[data-qa-target="pro-card-natural-1"]');
  const card2 = document.querySelector('[data-qa-target="pro-card-natural-2"]');

  function findObjectWithAddress(el) {
    const fiberKey = Object.keys(el).find(k => k.startsWith('__reactFiber$'));
    let fiber = el[fiberKey];
    while (fiber) {
      const props = fiber.memoizedProps;
      if (props) {
        for (const k of Object.keys(props)) {
          const val = props[k];
          if (val && typeof val === 'object' && !Array.isArray(val)) {
            if ('address' in val || 'distance' in val || 'street' in val) {
              // Return a shallow copy of non-DOM, non-circular properties
              const clean = {};
              for (const [propKey, propVal] of Object.entries(val)) {
                if (typeof propVal !== 'object' || propVal === null) {
                  clean[propKey] = propVal;
                } else if (Array.isArray(propVal)) {
                  clean[propKey] = propVal.map(item => (typeof item === 'object' ? Object.keys(item) : item));
                } else {
                  clean[propKey] = Object.keys(propVal);
                }
              }
              return clean;
            }
          }
        }
      }
      fiber = fiber.return;
    }
    return null;
  }

  return {
    obj1: findObjectWithAddress(card1),
    obj2: findObjectWithAddress(card2)
  };
});

